import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Troubleshoot port forwarding","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/upnpumpkin/docs/troubleshooting.md"},"headers":[],"relativePath":"packages/upnpumpkin/docs/troubleshooting.md","filePath":"packages/upnpumpkin/docs/troubleshooting.md","lastUpdated":1792508847000}`),a={name:`packages/upnpumpkin/docs/troubleshooting.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="troubleshoot-port-forwarding" tabindex="-1">Troubleshoot port forwarding <a class="header-anchor" href="#troubleshoot-port-forwarding" aria-label="Permalink to “Troubleshoot port forwarding”">​</a></h1><p>Start with <code>/upnp status</code>. It shows whether UPnPumpkin has found a router and whether each requested port is open, still being opened, or failed. The command&#39;s state helps narrow down which part of the network to check.</p><h2 id="no-router-is-found" tabindex="-1">No router is found <a class="header-anchor" href="#no-router-is-found" aria-label="Permalink to “No router is found”">​</a></h2><p>Make sure UPnP or NAT-PMP is enabled in the router settings and the server host is on the router&#39;s local network. UPnP normally uses multicast discovery. If the server&#39;s network blocks multicast, set <code>router.upnp_search</code> in <code>plugins/data/UPnPumpkin/config.toml</code> to the router&#39;s IPv4 address and UPnP port, for example <code>192.168.1.1:1900</code>. Run <code>/upnp reload</code> to apply the change.</p><p>If the reason says the plugin is not allowed to use the network that way, Pumpkin blocked the socket. Check that the plugin&#39;s <code>network.*</code> permissions were granted when Pumpkin asked on the console, and that <code>pumpkin.toml</code> doesn&#39;t list them in <code>plugins.blocked_permissions</code>. Also check that <code>plugins.loopback_only</code> is off, or that <code>[plugins.overrides.UPnPumpkin]</code> sets <code>loopback_only = false</code>. With it on, the plugin can only reach localhost, never the router.</p><p>For NAT-PMP, set <code>router.nat_pmp_gateway</code> to the gateway&#39;s IPv4 address and port (usually <code>192.168.1.1:5351</code>) if automatic probing does not find it. In a container or a network with multiple routers, check that the server can reach the router and receive its replies; a container network may not pass the discovery traffic the router needs.</p><h2 id="a-port-is-not-opened-or-players-cannot-connect" tabindex="-1">A port is not opened or players cannot connect <a class="header-anchor" href="#a-port-is-not-opened-or-players-cannot-connect" aria-label="Permalink to “A port is not opened or players cannot connect”">​</a></h2><p>In <code>/upnp status</code>, look at the state and reason shown for the Java and Bedrock ports. Confirm <code>java.port</code> and <code>bedrock.port</code> match the server listeners. Java uses TCP, and Bedrock uses both TCP and UDP on the same port. The router mapping does not change host firewall rules, so allow the same ports and protocols through the server&#39;s firewall.</p><p>The router also needs a public internet-side address to accept inbound connections. When it has none, the reason in <code>/upnp status</code> says why:</p><ul><li>Your provider shares one address between customers (carrier-grade NAT). Ask the provider for a public IPv4 address; no router setting fixes this.</li><li>Another router sits between yours and the internet (double NAT), for example the provider&#39;s modem. Forward the ports on that router, or put it in bridge mode so yours gets the public address.</li><li>The router has no internet connection right now, for example during a reconnect. UPnPumpkin tries again later.</li></ul><p>A server machine that already has a public address does not need a router mapping.</p><p>If <code>/upnp status</code> reports that the router is unsupported, UPnPumpkin intentionally opens nothing for that router. Forward the ports manually in the router settings instead.</p><h2 id="a-plugin-s-requested-port-closes-or-is-rejected" tabindex="-1">A plugin&#39;s requested port closes or is rejected <a class="header-anchor" href="#a-plugin-s-requested-port-closes-or-is-rejected" aria-label="Permalink to “A plugin&#39;s requested port closes or is rejected”">​</a></h2><p>Check that <code>plugins.allow_requests</code> is enabled and the requesting plugin is still refreshing its request. UPnPumpkin drops a request after five minutes without a refresh, and the requester should stop its watcher when it no longer needs the port. Each plugin can hold up to <code>plugins.max_requests_per_plugin</code> mappings at once; a request beyond that limit is rejected.</p><p>After changing settings in <code>plugins/data/UPnPumpkin/config.toml</code>, run <code>/upnp reload</code>. Changes also take effect after a server restart.</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};